   'data class Pengguna(val nama: String, val kota: String)\n\nsealed interface UiState {\n    data object Loading : UiState\n    data class Success(val data: List<Pengguna>) : UiState\n    data class Error(val pesan: String) : UiState\n}\n\nfun tampilkan(state: UiState) = when (state) {\n    UiState.Loading -> "Memuat..."\n    is UiState.Success -> "Ada ${state.data.size} pengguna"\n    is UiState.Error -> "Gagal: ${state.pesan}"\n}\n\nfun main() {\n    val rina = Pengguna("Rina", "Medan")\n    val pindah = rina.copy(kota = "Bandung")\n    println(rina)\n    println(pindah)\n    println(rina == Pengguna("Rina", "Medan"))\n    println(tampilkan(UiState.Loading))\n    println(tampilkan(UiState.Success(listOf(rina, pindah))))\n    println(tampilkan(UiState.Error("tidak ada internet")))\n}',
